import{_ as e,o,c as t,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Macro-Notes.md","filePath":"manual-zh/Macro-Notes.md","lastUpdated":1785684581000}'),d={name:"manual-zh/Macro-Notes.md"};function n(c,a,s,i,E,l){return o(),t("div",null,[...a[0]||(a[0]=[r('<h4 id="_14-2-12-additional-notes" tabindex="-1">14.2.12 Additional Notes <a class="header-anchor" href="#_14-2-12-additional-notes" aria-label="Permalink to &quot;14.2.12 Additional Notes&quot;">​</a></h4><h4 id="_14-2-12-1-calling-macros-from-macros" tabindex="-1">14.2.12.1 Calling Macros from Macros <a class="header-anchor" href="#_14-2-12-1-calling-macros-from-macros" aria-label="Permalink to &quot;14.2.12.1 Calling Macros from Macros&quot;">​</a></h4><p>如果宏 A 的主体包含对宏 B 的调用，则该调用可以使用宏参数（包括 <code>!*</code>）和宏变量作为 B 的参数的一部分。对于 <code>!TOKENS</code> 参数，参数或变量名算作一个记号，而不论其展开为多少；对于 <code>!CHAREND</code> 和 <code>!ENCLOSE</code> 参数，分隔符仅来自调用，而非展开；<code>!CMDEND</code> 在调用命令处结束，而非在参数或变量内的任何命令结束处。</p><p>宏函数不支持作为宏调用参数的组成部分。要获得相同效果，请使用 <code>!LET</code> 定义宏变量，然后将该宏变量传递给宏。</p><p>当宏 A 调用宏 B 时，它们 <code>DEFINE</code> 命令的顺序无关紧要，只要在调用 A 时宏 B 已经定义即可。</p><h4 id="_14-2-12-2-command-terminators" tabindex="-1">14.2.12.2 Command Terminators <a class="header-anchor" href="#_14-2-12-2-command-terminators" aria-label="Permalink to &quot;14.2.12.2 Command Terminators&quot;">​</a></h4><p>宏和命令终止符需要小心处理。宏遵循交互式与批处理语法之间的语法差异（参见 <a href="./Syntax-Variants">Syntax Variants</a>），这意味着宏的解释可能根据所使用的语法模式而变化。我们在此假设使用交互模式，其中行末的‘.’是结束命令的主要方式。</p><p><code>DEFINE</code> 命令需要以 <code>!ENDDEFINE</code> 之后的‘.’结束。如果宏主体旨在展开为完整命令，则它可能包含‘.’，但在展开为仅仅是语法片段（例如变量列表）的宏主体内部使用‘.’会导致语法错误。</p><p><code>!IF</code> 和 <code>!DO</code> 等宏指令不以‘.’结束。</p><h4 id="_14-2-12-3-expansion-contexts" tabindex="-1">14.2.12.3 Expansion Contexts <a class="header-anchor" href="#_14-2-12-3-expansion-contexts" aria-label="Permalink to &quot;14.2.12.3 Expansion Contexts&quot;">​</a></h4><p>宏不会在注释内展开，无论是通过 <code>/*</code> 在行内引入的注释，还是作为单独的 COMMENT 或‘<em>’命令（参见 <a href="./COMMENT">COMMENT</a>）。（SPSS 确实会在 COMMENT 和‘</em>’中展开宏。）</p><p>宏不会在带引号的字符串内展开。</p><p>只要参数不是带引号的字符串，宏就会在 <code>TITLE</code> 和 <code>SUBTITLE</code> 命令中展开。</p><h4 id="_14-2-12-4-preserve-and-restore" tabindex="-1">14.2.12.4 PRESERVE and RESTORE <a class="header-anchor" href="#_14-2-12-4-preserve-and-restore" aria-label="Permalink to &quot;14.2.12.4 PRESERVE and RESTORE&quot;">​</a></h4><p>某些宏主体可能使用 SET 命令更改某些设置。在这种情况下，考虑使用 PRESERVE 和 RESTORE 命令来保存并随后恢复这些设置。参见 <a href="./PRESERVE-and-RESTORE">PRESERVE and RESTORE</a>。</p>',15)])])}const h=e(d,[["render",n]]);export{p as __pageData,h as default};
